import{_ as o,o as r,c as t,ag as l}from"./chunks/framework.CAXxHpAX.js";const p=JSON.parse('{"title":"Deepsight Hello-Arch 架构设计 (v0.2)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dev/hello-arch.md","filePath":"guide/dev/hello-arch.md","lastUpdated":null}'),d={name:"guide/dev/hello-arch.md"};function c(n,e,s,a,i,g){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="deepsight-hello-arch-架构设计-v0-2" tabindex="-1">Deepsight Hello-Arch 架构设计 (v0.2) <a class="header-anchor" href="#deepsight-hello-arch-架构设计-v0-2" aria-label="Permalink to &quot;Deepsight Hello-Arch 架构设计 (v0.2)&quot;">​</a></h1><blockquote><p><strong>设计理念</strong>: “管道本身是防弹的，未来我们只是换掉管道里流动的水。” Hello-Arch 的核心目标不是完成某一个业务观测模块，而是构建一个可承载网络、存储、进程/调度三类模块逐步接入的 <strong>模块化底座框架</strong>。Hello 阶段保留 <code>execve</code> 作为真实健康检查事件，但它只是验证管线的样本，不代表进程模块已经完成。</p></blockquote><hr><h2 id="一、hello-底座完成边界" tabindex="-1">一、Hello 底座完成边界 <a class="header-anchor" href="#一、hello-底座完成边界" aria-label="Permalink to &quot;一、Hello 底座完成边界&quot;">​</a></h2><p>Hello 阶段必须完成三类稳定边界：</p><ol><li><strong>契约底座</strong>：Protobuf 从单个 <code>TelemetryEvent</code> 演进为 <code>TelemetryBatch</code> 总线，使用 <code>MetricWrapper</code> / <code>EventWrapper</code> 和 <code>oneof payload</code> 预留模块化扩展。</li><li><strong>通信底座</strong>：Probe 和 Server 不再写死 <code>127.0.0.1:50051</code>，统一通过 <code>Endpoint{network,address,tls}</code> 切换 TCP 与 UDS；TLS 配置结构存在，但 Hello 阶段显式拒绝 <code>tls.enabled=true</code>。</li><li><strong>配置底座</strong>：配置分为 Build、Release、Running 三层。运行时配置支持默认值、YAML、环境变量、CLI flag 覆盖，优先级为 <code>flag &gt; env &gt; config file &gt; defaults</code>。</li></ol><hr><h2 id="二、架构物理拆解" tabindex="-1">二、架构物理拆解 <a class="header-anchor" href="#二、架构物理拆解" aria-label="Permalink to &quot;二、架构物理拆解&quot;">​</a></h2><p>架构严格遵守<strong>职责单一</strong>和<strong>彻底解耦</strong>的原则，目前划分为六个核心底座模块。</p><h3 id="_1-契约中枢-protobuf" tabindex="-1">1. 契约中枢 (Protobuf) <a class="header-anchor" href="#_1-契约中枢-protobuf" aria-label="Permalink to &quot;1. 契约中枢 (Protobuf)&quot;">​</a></h3><p><strong>职责</strong>：定义探针与服务端之间不可变的通信骨架。 <strong>文件位置</strong>：<code>proto/common/common.proto</code>, <code>proto/modules/*.proto</code>, <code>proto/v1/telemetry.proto</code><strong>详细文档</strong>：<a href="/guide/dev/proto/proto">Protobuf 契约设计总览</a><strong>设计细节</strong>：</p><ul><li><code>proto/common</code> 定义全局枚举，如 <code>Severity</code>、<code>Status</code>、<code>Action</code>。</li><li><code>proto/modules</code> 为网络、存储、进程模块提供最小强类型壳：<code>NetworkMetric/Event</code>、<code>StorageMetric/Event</code>、<code>ProcessMetric/Event</code>。</li><li><code>proto/v1/telemetry.proto</code> 定义稳定总线：<code>Register</code>、<code>PushTelemetry(stream TelemetryBatch)</code> 与明确返回未实现的 <code>TaskChannel</code> 预留接口。</li><li>Hello 阶段不提前写死各模块的完整业务字段，只保证后续模块能接入 <code>oneof payload</code>。</li></ul><h3 id="_2-内核挖矿机-ebpf-c代码" tabindex="-1">2. 内核挖矿机 (eBPF C代码) <a class="header-anchor" href="#_2-内核挖矿机-ebpf-c代码" aria-label="Permalink to &quot;2. 内核挖矿机 (eBPF C代码)&quot;">​</a></h3><p><strong>职责</strong>：在 Linux 内核态执行极低开销的系统调用挂载，提取数据并抛到用户态。 <strong>文件位置</strong>：<code>probe/bpf/tracer.bpf.c</code><strong>设计细节</strong>：</p><ul><li>探针锚点：Hello 健康检查安全地挂载在 <code>sys_enter_execve</code>（进程执行）系统调用上。</li><li>通信机制：申请了 <code>BPF_MAP_TYPE_RINGBUF</code> (环形缓冲区) 用于高性能异步传递数据。</li><li>工作流：捕获到新进程 -&gt; 获取 PID 和命令名 -&gt; 塞入 RingBuffer -&gt; 提交。</li><li>边界说明：该事件被映射为 <code>ProcessEvent{event_type=&quot;execve&quot;, pid, comm}</code>，仅用于验证模块化总线。</li></ul><h3 id="_3-用户态加载与流转-probe-go-端" tabindex="-1">3. 用户态加载与流转 (Probe Go 端) <a class="header-anchor" href="#_3-用户态加载与流转-probe-go-端" aria-label="Permalink to &quot;3. 用户态加载与流转 (Probe Go 端)&quot;">​</a></h3><p><strong>职责</strong>：作为探针宿主，负责 eBPF 的生命周期管理以及数据的网络转发。 <strong>文件位置</strong>：<code>probe/loader/loader.go</code>, <code>probe/transformer/transformer.go</code>, <code>probe/exporter/exporter.go</code><strong>设计细节</strong>：</p><ul><li><strong>解耦流转 (Channel Pattern)</strong>： <ul><li><code>loader</code> 模块负责调用 <code>bpf2go</code> 加载字节码，并将 RingBuffer 数据转换为 Probe 内部 <code>RawEvent</code>。</li><li><code>transformer</code> 模块负责 <code>RawEvent -&gt; TelemetryBatch</code>，当前只做 <code>execve -&gt; ProcessEvent</code>，同时预留限流、字典压缩、事件富化入口；开启限流配置时会输出 warning。</li><li><code>exporter</code> 模块作为 gRPC Client，只消费 <code>TelemetryBatch</code>，不关心具体业务模块。</li><li><code>exporter</code> 建立连接后先调用 <code>Register</code> 获取 Hello 阶段 session token，并注入后续 batch。</li></ul></li><li><strong>扩展性预留</strong>：未来网络、存储、调度模块只需新增 loader/transformer 分支，不需要改 exporter 主链路。</li></ul><h3 id="_4-中心接入与分发-server-go-端" tabindex="-1">4. 中心接入与分发 (Server Go 端) <a class="header-anchor" href="#_4-中心接入与分发-server-go-端" aria-label="Permalink to &quot;4. 中心接入与分发 (Server Go 端)&quot;">​</a></h3><p><strong>职责</strong>：高性能接收各节点探针推上来的数据流，并作落盘或二次分发。 <strong>文件位置</strong>：<code>server/ingester/grpc_server.go</code>, <code>server/dispatcher/dispatcher.go</code>, <code>server/buffer/memory.go</code><strong>设计细节</strong>：</p><ul><li><code>ingester</code> 只负责 gRPC 接收，不绑定具体 payload。</li><li><code>dispatcher</code> 根据 <code>MetricWrapper</code> / <code>EventWrapper</code> 的 <code>oneof</code> payload 识别模块类型并分发。</li><li><code>buffer</code> 当前提供内存窗口最小实现，后续替换为滑动窗口、事件防抖与 KV 持久化。</li><li>使用 Go 原生 <code>slog</code> 输出日志，<code>log.format</code> 支持 <code>json/text</code>。</li></ul><h3 id="_5-传输抽象-tcp-uds-tls-stub" tabindex="-1">5. 传输抽象 (TCP / UDS / TLS Stub) <a class="header-anchor" href="#_5-传输抽象-tcp-uds-tls-stub" aria-label="Permalink to &quot;5. 传输抽象 (TCP / UDS / TLS Stub)&quot;">​</a></h3><p><strong>职责</strong>：让运行方式由配置决定，而不是写死在代码里。 <strong>文件位置</strong>：<code>internal/config/transport.go</code><strong>设计细节</strong>：</p><ul><li>Server 使用 <code>network=tcp|unix</code> 调用 <code>net.Listen(network, address)</code>。</li><li>Probe 使用同一 <code>Endpoint</code> 生成 gRPC dial target。</li><li>默认开发模式为 TCP：<code>127.0.0.1:50051</code>。</li><li>单机性能模式可切换为 UDS：<code>/var/run/deepsight/deepsight.sock</code>。</li><li>TLS 字段已经存在，但 Hello 阶段只允许 <code>enabled=false</code>，开启时启动直接失败，避免产生“看似加密实际未加密”的错觉。</li></ul><h3 id="_6-配置底座-build-release-running" tabindex="-1">6. 配置底座 (Build / Release / Running) <a class="header-anchor" href="#_6-配置底座-build-release-running" aria-label="Permalink to &quot;6. 配置底座 (Build / Release / Running)&quot;">​</a></h3><p><strong>职责</strong>：为后续大量模块配置建立规则。 <strong>文件位置</strong>：<code>internal/config/</code>, <code>configs/*.example.yaml</code><strong>设计细节</strong>：</p><ul><li><strong>Build 配置</strong>：继续由 <code>Makefile</code> 管理 proto 生成、bpf2go、include path 和编译产物。</li><li><strong>Release 配置</strong>：提供 <code>configs/probe.example.yaml</code> 与 <code>configs/server.example.yaml</code> 作为交付模板。</li><li><strong>Running 配置</strong>：程序启动时读取默认值、YAML、环境变量和 CLI flag，优先级为 <code>flag &gt; env &gt; config file &gt; defaults</code>。</li><li>当前配置包含：日志、模块启用状态、channel buffer、transformer 限流 stub、memory buffer 大小、endpoint；三个模块不能全部禁用，<code>process=false</code> 会禁用 execve loader。</li><li>详细设计见：<a href="/guide/dev/config">配置系统设计</a>。</li></ul><hr><h2 id="三、-与总体架构设计的映射关系" tabindex="-1">三、 与总体架构设计的映射关系 <a class="header-anchor" href="#三、-与总体架构设计的映射关系" aria-label="Permalink to &quot;三、 与总体架构设计的映射关系&quot;">​</a></h2><p>Hello-Arch 并非一个简单的玩具 Demo，而是完整 Deepsight 系统架构（对应 <code>01_deepsight.md</code> 与 <code>deepsight-arch.drawio.png</code>）的<strong>最小可行性底座（MVP-Foundation）</strong>。它打通了跨越“异构语言”、“内核态边界”、“并发解耦”、“RPC 长连接”、“模块契约”和“运行配置”的全链路血管。</p><h3 id="_1-模块映射对齐" tabindex="-1">1. 模块映射对齐 <a class="header-anchor" href="#_1-模块映射对齐" aria-label="Permalink to &quot;1. 模块映射对齐&quot;">​</a></h3><ul><li><strong>eBPF 探针侧 (Kernel Space)</strong>： <ul><li><strong>实现现状</strong>：在 <code>tracer.bpf.c</code> 中通过 RingBuf 实现了内核态到用户态的数据抛出。</li><li><strong>对应图纸</strong>：架构图最底层的“内核态采集节点”。</li></ul></li><li><strong>用户态流转端 (Probe Edge)</strong>： <ul><li><strong>实现现状</strong>：<code>loader.go</code>、<code>transformer.go</code> 与 <code>exporter.go</code> 已形成 Channel 管线。</li><li><strong>留白预留</strong>：<code>transformer</code> 当前只做最小转换，未来承接字典压缩、令牌桶限流与数据富化。</li></ul></li><li><strong>中心控制台 (Server Center)</strong>： <ul><li><strong>实现现状</strong>：<code>grpc_server.go</code>、<code>dispatcher.go</code>、<code>memory.go</code> 已形成接收、分发、缓存的最小链路。</li><li><strong>留白预留</strong>：后端的事件防抖、KV 持久化、MCP Resources/Tools 尚未实装。</li></ul></li></ul><h3 id="_2-网络通信选型与演进-uds-vs-tcp-tls" tabindex="-1">2. 网络通信选型与演进 (UDS vs TCP/TLS) <a class="header-anchor" href="#_2-网络通信选型与演进-uds-vs-tcp-tls" aria-label="Permalink to &quot;2. 网络通信选型与演进 (UDS vs TCP/TLS)&quot;">​</a></h3><p>在当前 Hello-Arch 的代码基线中，为了快速验证全链路，默认采用 <strong>无加密的 TCP 通信（gRPC over TCP, insecure）</strong>：</p><ul><li><strong>服务端默认配置</strong>：<code>network: tcp</code>, <code>address: 127.0.0.1:50051</code></li><li><strong>探针默认配置</strong>：<code>network: tcp</code>, <code>address: 127.0.0.1:50051</code>, <code>tls.enabled: false</code></li></ul><p>这种“配置驱动 Endpoint”的起手式，实际上是为<strong>单机 UDS</strong> 与 <strong>分布式 TCP/TLS</strong> 双轨通信打下代码骨架：</p><ol><li><strong>单机极限性能 (gRPC over UDS)</strong>：将配置切换为 <code>network: unix</code> 与 socket 路径即可。</li><li><strong>分布式安全通信 (gRPC over TCP/mTLS)</strong>：TLS 字段已在配置结构中预留，后续实现证书加载即可；Hello 阶段显式拒绝启用 TLS。</li></ol><hr><h2 id="四、-自动化工程与验证链路" tabindex="-1">四、 自动化工程与验证链路 <a class="header-anchor" href="#四、-自动化工程与验证链路" aria-label="Permalink to &quot;四、 自动化工程与验证链路&quot;">​</a></h2><p>在开发与验证环境体验上，项目设计了完整的脚本矩阵闭环：</p><ul><li><strong>自动化构建</strong>：<code>Makefile</code> 封装了 <code>go generate</code> (BPF 编译) 和 <code>go build</code>。</li><li><strong>一键运行 Server</strong>：<code>scripts/dev/run_server.sh</code> 负责编译并在 <code>50051</code> 端口拉起服务端。</li><li><strong>一键运行 Probe</strong>：<code>scripts/dev/run_probe.sh</code> 负责编译、代码生成，并自动 <code>sudo</code> 提权拉起探针客户端。</li><li><strong>自动化负载测试</strong>：<code>scripts/tests/trigger_execve.sh</code> 负责在系统中精准制造各类（常规、特征、密集）进程执行事件，直接刺激探针捕获，打通首尾反馈回路。</li></ul><h2 id="五、-hello-完成标准" tabindex="-1">五、 Hello 完成标准 <a class="header-anchor" href="#五、-hello-完成标准" aria-label="Permalink to &quot;五、 Hello 完成标准&quot;">​</a></h2><ol><li><code>PushTelemetry</code> 使用 <code>TelemetryBatch</code>，而不是单个 <code>pid/comm</code> 事件。</li><li><code>proto/common</code>、<code>proto/modules</code>、<code>proto/v1</code> 分层存在，并可生成 Go API。</li><li>Probe 主链路为 <code>loader -&gt; transformer -&gt; exporter</code>，并在 exporter 侧完成最小 Register/session token 闭环。</li><li>Server 主链路为 <code>ingester -&gt; dispatcher -&gt; buffer</code>。</li><li>TCP 默认链路仍能跑通 <code>execve</code> hello 事件。</li><li>UDS 可通过配置切换，不需要改代码。</li><li>配置系统已经具备 Build/Release/Running 三层骨架。</li></ol><h2 id="六、-演进路线图" tabindex="-1">六、 演进路线图 <a class="header-anchor" href="#六、-演进路线图" aria-label="Permalink to &quot;六、 演进路线图&quot;">​</a></h2><p>基于目前的 Hello-Arch，下一步的演进（v0.2+）将完全不需要推翻当前代码，而是做“加法”：</p><ol><li><strong>网络模块</strong>：新增 <code>tcp_connect</code> / <code>kfree_skb</code> 等探针，扩展 <code>NetworkMetric/Event</code>。</li><li><strong>存储模块</strong>：新增慢 I/O、块设备延迟等探针，扩展 <code>StorageMetric/Event</code>。</li><li><strong>进程/调度模块</strong>：从当前 <code>execve</code> 健康检查演进到调度延迟、上下文切换等事件。</li><li><strong>Probe 层</strong>：补全 transformer 的令牌桶限流、字典压缩与符号翻译。</li><li><strong>Server 层</strong>：将 memory buffer 扩展为滑动窗口、事件防抖和 KV 持久化。</li></ol>',46)])])}const u=o(d,[["render",c]]);export{p as __pageData,u as default};
